from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    fill = counts.most_common(1)[0][0]

    # Rail color is distinct from the dominant cell-interior color and forms
    # repeated nearly-solid horizontal and vertical grid lines.
    candidates = []
    for color in counts:
        if color == fill:
            continue
        rows = [r for r in range(h) if sum(v == color for v in grid[r]) >= 0.65 * w]
        cols = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= 0.65 * h]
        if len(rows) >= 2 and len(cols) >= 2:
            candidates.append((len(rows) + len(cols), color, rows, cols))
    if not candidates:
        raise ValueError('lattice rails not found')
    _, rail, row_lines, col_lines = max(candidates)

    # Each output cell corresponds to a rectangle between neighboring rails.
    # Matching colored corner markers fill it; other rectangles retain the
    # interior color. Unmarked outer margins are cropped afterward.
    out = []
    for r0, r1 in zip(row_lines, row_lines[1:]):
        row = []
        for c0, c1 in zip(col_lines, col_lines[1:]):
            corners = [grid[r][c] for r, c in ((r0, c0), (r0, c1), (r1, c0), (r1, c1))]
            if corners[0] not in (fill, rail) and all(v == corners[0] for v in corners):
                row.append(corners[0])
            else:
                row.append(fill)
        out.append(row)

    while len(out) > 1 and all(v == fill for v in out[0]):
        out.pop(0)
    while len(out) > 1 and all(v == fill for v in out[-1]):
        out.pop()
    while len(out[0]) > 1 and all(row[0] == fill for row in out):
        for row in out:
            row.pop(0)
    while len(out[0]) > 1 and all(row[-1] == fill for row in out):
        for row in out:
            row.pop()
    return out

